DO $g$ DECLARE
  v_stage_count integer;
  v_dup_count integer;
  v_tbl_exists integer;
  v_pk_cols integer;
  v_unmatched integer;
BEGIN
  -- Guard 1: stage row count == expected D5 total
  SELECT count(*) INTO v_stage_count FROM stage_030_d5;
  IF v_stage_count <> 14222 THEN
    RAISE EXCEPTION '030 guard: stage row count % != expected 14222', v_stage_count;
  END IF;
  -- Guard 2: no duplicate (breaker_class, source_id) in stage
  SELECT count(*) INTO v_dup_count FROM (
    SELECT breaker_class, source_id FROM stage_030_d5
    GROUP BY breaker_class, source_id HAVING count(*) > 1
  ) dups;
  IF v_dup_count > 0 THEN
    RAISE EXCEPTION '030 guard: % duplicate (breaker_class, source_id) pair(s) in stage', v_dup_count;
  END IF;
  -- Guard 3: DDL present -- tcc.brk_style_native_overrides exists with PK (breaker_class, source_id)
  SELECT count(*) INTO v_tbl_exists FROM information_schema.tables
    WHERE table_schema='tcc' AND table_name='brk_style_native_overrides';
  IF v_tbl_exists <> 1 THEN
    RAISE EXCEPTION '030 guard: tcc.brk_style_native_overrides does not exist';
  END IF;
  -- PATCH 4: exact-2 PK guard matching the queued DDL (030_d5_native_overrides_sidetable.sql).
  -- Step 1: total PK column count must be exactly 2.
  SELECT count(*) INTO v_pk_cols
    FROM information_schema.table_constraints tc
    JOIN information_schema.key_column_usage kcu
      ON kcu.constraint_schema = tc.constraint_schema
      AND kcu.constraint_name = tc.constraint_name
    WHERE tc.table_schema='tcc' AND tc.table_name='brk_style_native_overrides'
      AND tc.constraint_type='PRIMARY KEY';
  IF v_pk_cols <> 2 THEN
    RAISE EXCEPTION '030 guard: PK has % column(s), expected exactly 2 (breaker_class, source_id)', v_pk_cols;
  END IF;
  -- Step 2: membership check -- the 2 PK columns must be exactly (breaker_class, source_id).
  IF (SELECT count(*) FROM information_schema.table_constraints tc
        JOIN information_schema.key_column_usage kcu
          ON kcu.constraint_schema = tc.constraint_schema
          AND kcu.constraint_name = tc.constraint_name
        WHERE tc.table_schema='tcc' AND tc.table_name='brk_style_native_overrides'
          AND tc.constraint_type='PRIMARY KEY'
          AND kcu.column_name IN ('breaker_class','source_id')) <> 2 THEN
    RAISE EXCEPTION '030 guard: PK columns are not exactly (breaker_class, source_id)';
  END IF;
  -- Guard 4: coverage anti-join -- every stage (breaker_class, source_id)
  --   must join its per-class style table source_id
  SELECT count(*) INTO v_unmatched FROM (
    SELECT st.breaker_class, st.source_id
    FROM stage_030_d5 st
    WHERE st.breaker_class = 'ICCB'
      AND NOT EXISTS (SELECT 1 FROM tcc.brk_iccb_styles s WHERE s.source_id = st.source_id)
    UNION ALL
    SELECT st.breaker_class, st.source_id
    FROM stage_030_d5 st
    WHERE st.breaker_class = 'MCCB'
      AND NOT EXISTS (SELECT 1 FROM tcc.brk_mccb_styles s WHERE s.source_id = st.source_id)
    UNION ALL
    SELECT st.breaker_class, st.source_id
    FROM stage_030_d5 st
    WHERE st.breaker_class = 'PCB'
      AND NOT EXISTS (SELECT 1 FROM tcc.brk_pcb_styles s WHERE s.source_id = st.source_id)
  ) unmatched;
  IF v_unmatched > 0 THEN
    RAISE EXCEPTION '030 guard: % stage (breaker_class, source_id) pair(s) have no match in the per-class style table (orphan rows)', v_unmatched;
  END IF;
END $g$;
INSERT INTO tcc.brk_style_native_overrides
  (breaker_class, source_id, inst_override, ninst_override,
   brk_times, r_int, r_iec, ovr_curves)
SELECT breaker_class, source_id, inst_override, ninst_override,
       brk_times, r_int, r_iec, NULL
FROM stage_030_d5
ON CONFLICT (breaker_class, source_id) DO UPDATE SET
  inst_override  = EXCLUDED.inst_override,
  ninst_override = EXCLUDED.ninst_override,
  brk_times      = EXCLUDED.brk_times,
  r_int          = EXCLUDED.r_int,
  r_iec          = EXCLUDED.r_iec,
  ovr_curves     = EXCLUDED.ovr_curves;
DO $pw$ DECLARE v_written integer; v_expected integer;
BEGIN
  SELECT count(*) INTO v_expected FROM stage_030_d5;
  SELECT count(*) INTO v_written
    FROM stage_030_d5 st
    JOIN tcc.brk_style_native_overrides t
      ON t.breaker_class = st.breaker_class AND t.source_id = st.source_id;
  IF v_written <> v_expected THEN
    -- single % below is a literal PL/pgSQL placeholder -- NOT a Python %-format target
    RAISE EXCEPTION '030 post-write: only % of % rows present in target after INSERT', v_written, v_expected;
  END IF;
END $pw$;
DO $vp$ DECLARE v_mismatch integer;
BEGIN
  -- 030 value-parity guard: for each staged row, target payload must match stage.
  -- Guards against a future broken UPDATE clause leaving stale JSONB.
  SELECT count(*) INTO v_mismatch
    FROM stage_030_d5 st
    JOIN tcc.brk_style_native_overrides t
      ON t.breaker_class = st.breaker_class AND t.source_id = st.source_id
    WHERE NOT (
          t.inst_override  IS NOT DISTINCT FROM st.inst_override
      AND t.ninst_override IS NOT DISTINCT FROM st.ninst_override
      AND t.brk_times      IS NOT DISTINCT FROM st.brk_times
      AND t.r_int          IS NOT DISTINCT FROM st.r_int
      AND t.r_iec          IS NOT DISTINCT FROM st.r_iec
      AND t.ovr_curves IS NULL
    );
  IF v_mismatch > 0 THEN
    -- single % below is a literal PL/pgSQL placeholder -- NOT a Python %-format target
    RAISE EXCEPTION '030 value-parity: % staged row(s) have mismatched payload in target after INSERT', v_mismatch;
  END IF;
END $vp$;
DO $xr$ DECLARE v_extra integer;
BEGIN
  -- Extra-row guard: target must not contain (breaker_class, source_id) rows
  -- that are absent from stage_030_d5 for any class the stage covers.
  SELECT count(*) INTO v_extra
    FROM tcc.brk_style_native_overrides t
    -- Restrict to classes the stage carries (avoid flagging unrelated classes)
    WHERE t.breaker_class IN (SELECT DISTINCT breaker_class FROM stage_030_d5)
      AND NOT EXISTS (
        SELECT 1 FROM stage_030_d5 st
        WHERE st.breaker_class = t.breaker_class AND st.source_id = t.source_id
      );
  IF v_extra > 0 THEN
    -- single % below is a literal PL/pgSQL placeholder -- NOT a Python %-format target
    RAISE EXCEPTION '030 extra-row guard: % stale (breaker_class, source_id) row(s) in target outside the staged keyset -- polluted prior apply detected', v_extra;
  END IF;
END $xr$;
COMMIT;
